// Test support for the Swift probe fixtures in tests/fixtures/swift (generated by the
// programs in tests/fixtures/swift/probes). Test-only: uses node: modules.
import { readFileSync } from 'node:fs';
import { gunzipSync } from 'node:zlib';

const fixtures = new URL('../fixtures/', import.meta.url);

/** Reads `tests/fixtures/<relative>` as bytes, transparently gunzipping `*.gz`. */
export function fixtureBytes(relative: string): Uint8Array {
  const raw = readFileSync(new URL(relative, fixtures));
  return new Uint8Array(relative.endsWith('.gz') ? gunzipSync(raw) : raw);
}

export function fixtureText(relative: string): string {
  return new TextDecoder().decode(fixtureBytes(relative));
}

/** Lines of `section` in a probe dump: everything after the line `name` up to the next all-caps header. */
export function probeSection(text: string, name: string): string[] {
  const lines = text.split('\n');
  const start = lines.indexOf(name);
  if (start < 0) throw new Error(`missing probe section ${name}`);
  const out: string[] = [];
  for (let i = start + 1; i < lines.length; i++) {
    const line = lines[i] as string;
    if (/^[A-Z][A-Z_0-9]*( .*)?$/.test(line)) break;
    out.push(line);
  }
  return out;
}

/** Value after `name ` on its own line, e.g. `ROUNDED_HASH 1710144063`. */
export function probeValue(text: string, name: string): string {
  const line = text.split('\n').find((l) => l.startsWith(name + ' '));
  if (line === undefined) throw new Error(`missing probe value ${name}`);
  return line.slice(name.length + 1);
}

const view = new DataView(new ArrayBuffer(8));

/** Swift `String(d.bitPattern, radix: 16)` → Double. */
export function hexToDouble(hex: string): number {
  view.setBigUint64(0, BigInt('0x' + hex));
  return view.getFloat64(0);
}

export function doubleToHex(x: number): string {
  view.setFloat64(0, x);
  return view.getBigUint64(0).toString(16);
}

const TWO_32 = 4294967296;

/** (a × b) mod 2^64 on 32-bit halves, exact in doubles. Returns [hi, lo]. */
function mul64(aHi: number, aLo: number, bHi: number, bLo: number): [number, number] {
  const a0 = aLo & 0xffff;
  const a1 = aLo >>> 16;
  const b0 = bLo & 0xffff;
  const b1 = bLo >>> 16;
  const mid = a0 * b1 + a1 * b0;
  const low = a0 * b0 + (mid % 65536) * 65536;
  const lo = low % TWO_32;
  const hi = (a1 * b1 + Math.floor(mid / 65536) + Math.floor(low / TWO_32) + Math.imul(aHi, bLo) + Math.imul(aLo, bHi)) >>> 0;
  return [hi, lo >>> 0];
}

/** The SplitMix64 generator of the Swift probes (`state &+= 0x9E3779B97F4A7C15; …`). */
export class SplitMix64 {
  private hi: number;
  private lo: number;
  /** Upper and lower 32 bits of the last output. */
  outHi = 0;
  outLo = 0;

  constructor(seed: bigint) {
    this.hi = Number((seed >> 32n) & 0xffffffffn);
    this.lo = Number(seed & 0xffffffffn);
  }

  next(): void {
    const lo = this.lo + 0x7f4a7c15;
    this.lo = lo >>> 0;
    this.hi = (this.hi + 0x9e3779b9 + (lo >= TWO_32 ? 1 : 0)) >>> 0;
    let zHi = this.hi;
    let zLo = this.lo;
    // z = (z ^ (z >> 30)) &* 0xBF58476D1CE4E5B9
    [zHi, zLo] = mul64(zHi ^ (zHi >>> 30), (zLo ^ ((zLo >>> 30) | (zHi << 2))) >>> 0, 0xbf58476d, 0x1ce4e5b9);
    // z = (z ^ (z >> 27)) &* 0x94D049BB133111EB
    [zHi, zLo] = mul64(zHi ^ (zHi >>> 27), (zLo ^ ((zLo >>> 27) | (zHi << 5))) >>> 0, 0x94d049bb, 0x133111eb);
    // z ^ (z >> 31)
    this.outHi = (zHi ^ (zHi >>> 31)) >>> 0;
    this.outLo = (zLo ^ ((zLo >>> 31) | (zHi << 1))) >>> 0;
  }

  /** Swift `next() % m` for a small modulus. */
  mod(m: number): number {
    this.next();
    return ((this.outHi % m) * (TWO_32 % m) + (this.outLo % m)) % m;
  }

  /** Swift `Double(next() >> 11) * 0x1p-53`. */
  unit(): number {
    this.next();
    return (this.outHi * 2097152 + (this.outLo >>> 11)) * 1.1102230246251565e-16;
  }

  /** Swift `Double(bitPattern: next())`, replaced by 1.0 when not finite. */
  rawFinite(): number {
    this.next();
    view.setUint32(0, this.outHi);
    view.setUint32(4, this.outLo);
    const d = view.getFloat64(0);
    return Number.isFinite(d) ? d : 1.0;
  }

  /** The full 64-bit output as a BigInt (slow; for spot checks). */
  nextBig(): bigint {
    this.next();
    return (BigInt(this.outHi) << 32n) | BigInt(this.outLo);
  }
}

/** FNV-1a (32 bit) over the little-endian bit patterns of doubles, as in the Swift probes. */
export class Fnv32 {
  h = 0x811c9dc5;
  private readonly bytes = new Uint8Array(8);
  private readonly dv = new DataView(this.bytes.buffer);

  add(x: number): void {
    this.dv.setFloat64(0, x, true);
    let h = this.h;
    for (let i = 0; i < 8; i++) {
      h ^= this.bytes[i] as number;
      h = Math.imul(h, 0x01000193);
    }
    this.h = h >>> 0;
  }
}
